    sel.innerHTML = Object.entries(groups).map(([g, list]) => `<optgroup label="${esc(g)}">` +
      list.map(([k, s]) => `<option value="${k}">${s[2] != null ? '/*' + pc4(s[2]) + '*/ ' : ''}${esc(s[5])}</option>`).join('') + '</optgroup>').join('');
